function measure(text, size) {
  const row = MATRIX[size];
  if (!row) return 999999; // unvisited size: fail closed
  const w = row[text];
  return w === undefined ? 999999 : w;
}
function currentSize(font) {
  const m = /bold (\d+)px/.exec(font);
  return m ? Number(m[1]) : BASE_SIZE;
}
const ctx = {
  font: '',
  measureText: (text) => ({ width: measure(text, currentSize(ctx.font)) }),
};

const EXPECTED = [
  // Pre-fix Chromium layouts (qa/_tmp-vis003-fix-sim.mjs, 2026-10-23).
  // The two connector-initial defects get their post-fix expected values;
  // the other five are pinned byte-exact as regression guards.
  { title: 'Cloud & Infrastructure', size: 196, lines: ['Cloud &', 'Infrastructure'] },
  { title: 'CI/CD & Observability', size: 208, lines: ['CI/CD &', 'Observability'] },
  { title: 'Containerization', size: 172, lines: ['Containerization'] },
  { title: 'Development & Automation', size: 184, lines: ['Development &', 'Automation'] },
  { title: 'RxVerify — Digital Prescription Verification', size: 160, lines: ['RxVerify — Digital', 'Prescription', 'Verification'] },
  { title: 'Full-Stack AI DevOps Masterclass', size: 244, lines: ['Full-Stack', 'AI DevOps', 'Masterclass'] },
  { title: 'Go Microservices — Real-Time Balance Visibility', size: 148, lines: ['Go Microservices —', 'Real-Time Balance', 'Visibility'] },
];

const results = [];
function check(name, cond, detail) {
  results.push({ name, pass: !!cond, detail });
  console.log(`${cond ? '\u2705' : '\u274c'} ${name}${detail ? ' — ' + detail : ''}`);
}

const maxW = CANVAS_W * MAX_W_FRAC;
const maxH = CANVAS_H * MAX_H_FRAC;
const CONNECTORS = new Set(['&', '/', '+', '\u2014', '-', '\u00b7']);

for (const exp of EXPECTED) {
  const L = computeTitleLayout(ctx, exp.title, true);
  const layoutStr = `${L.size}px [${L.lines.join(' | ')}]`;
  const expectedStr = `${exp.size}px [${exp.lines.join(' | ')}]`;
  check(`layout match: ${exp.title}`, L.size === exp.size && JSON.stringify(L.lines) === JSON.stringify(exp.lines), `got ${layoutStr} want ${expectedStr}`);
  for (const line of L.lines) {
    const t = line.trim();
    check(`no bare-connector line: "${t}"`, !CONNECTORS.has(t));
    check(`no connector-INITIAL line: "${t}"`, !CONNECTORS.has(t[0]));
  }
  const widest = Math.max(...L.lines.map((l) => measure(l, L.size)));
  check(`fits maxW: ${exp.title}`, widest <= maxW, `${Math.round(widest)}px <= ${Math.round(maxW)}px`);
  check(`fits maxH: ${exp.title}`, L.size * 1.08 * L.lines.length <= maxH, `${Math.round(L.size * 1.08 * L.lines.length)} <= ${Math.round(maxH)}`);
  check(`size >= floor: ${exp.title}`, L.size >= TITLE_FLOOR_BIG, `${L.size} >= ${TITLE_FLOOR_BIG}`);
}

console.log(`\n=== VIS-003 TITLE LAYOUT: ${results.filter(r => r.pass).length}/${results.length} pass ===`);
if (results.some(r => !r.pass)) process.exit(1);
